1. import PostHog from 'posthog-react-native';
2. import type * as PostHogType from '.';
3. 
4. const mockPostHogClient = {
5.   capture: jest.fn(),
6.   screen: jest.fn(),
7.   identify: jest.fn(),
8.   register: jest.fn(),
9.   optIn: jest.fn(),
10.   optOut: jest.fn(),
11. };
12. jest.mock('posthog-react-native', () => ({
13.   initAsync: jest.fn(() => mockPostHogClient),
14. }));
15. 
16. jest.mock('../../constants', () => ({
17.   DEFAULT_CONSENT: false,
18. }));
19. 
20. afterEach(() => {
21.   jest.clearAllMocks();
22. });
23. 
24. let postHog: typeof PostHogType;
25. beforeEach(() => {
26.   jest.isolateModules(() => {
27.     // PostHog library is unfortunately statefull
28.     postHog = require('./index');
29.   });
30. });
31. 
32. describe('init', () => {
33.   it('initializes postHog', async () => {
34.     await postHog.init();
35. 
36.     expect(PostHog.initAsync).toHaveBeenCalledTimes(1);
37.     expect(PostHog.initAsync).toHaveBeenCalledWith('some-posthog-api-key', {
38.       host: 'https://eu.posthog.com',
39.     });
40.   });
41. 
42.   it('never initializes twice', async () => {
43.     await postHog.init();
44.     await postHog.init();
45. 
46.     expect(PostHog.initAsync).toHaveBeenCalledTimes(1);
47.     expect(PostHog.initAsync).toHaveBeenCalledWith('some-posthog-api-key', {
48.       host: 'https://eu.posthog.com',
49.     });
50.   });
51. 
52.   it('sets default consent', async () => {
53.     await postHog.init();
54. 
55.     expect(mockPostHogClient.optOut).toHaveBeenCalledTimes(1);
56.     expect(mockPostHogClient.optIn).toHaveBeenCalledTimes(0);
57.   });
58. });
59. 
60. describe('setConsent', () => {
61.   it('makes sure postHog is initalized', async () => {
62.     await postHog.setConsent(true);
63. 
64.     expect(PostHog.initAsync).toHaveBeenCalledTimes(1);
65.   });
66. 
67.   it('calls optIn on true', async () => {
68.     await postHog.setConsent(true);
69.     expect(mockPostHogClient.optOut).toHaveBeenCalledTimes(1); // at init
70.     expect(mockPostHogClient.optIn).toHaveBeenCalledTimes(1);
71.   });
72. 
73.   it('calls optOut on false', async () => {
74.     await postHog.setConsent(false);
75.     expect(mockPostHogClient.optOut).toHaveBeenCalledTimes(2); // first at init
76.     expect(mockPostHogClient.optIn).toHaveBeenCalledTimes(0);
77.   });
78. });
79. 
80. describe('logEvent', () => {
81.   it('requires an init first', async () => {
82.     await postHog.logEvent('Screen', {'Screen Name': 'some-screen'});
83. 
84.     expect(mockPostHogClient.capture).toHaveBeenCalledTimes(0);
85.   });
86. 
87.   it('calls capture', async () => {
88.     await postHog.init();
89.     await postHog.logEvent('Screen', {'Screen Name': 'some-screen'});
90. 
91.     expect(mockPostHogClient.capture).toHaveBeenCalledTimes(1);
92.     expect(mockPostHogClient.capture).toHaveBeenCalledWith('Screen', {
93.       'Screen Name': 'some-screen',
94.     });
95.   });
96. });
97. 
98. describe('logNavigation', () => {
99.   it('requires an init first', async () => {
100.     await postHog.logNavigation('Some Screen');
101. 
102.     expect(mockPostHogClient.screen).toHaveBeenCalledTimes(0);
103.   });
104. 
105.   it('calls screen', async () => {
106.     await postHog.init();
107.     await postHog.logNavigation('Some Screen', {Origin: 'some-origin'});
108. 
109.     expect(mockPostHogClient.screen).toHaveBeenCalledTimes(1);
110.     expect(mockPostHogClient.screen).toHaveBeenCalledWith('Some Screen', {
111.       Origin: 'some-origin',
112.     });
113.   });
114. });
115. 
116. describe('setUserProperties', () => {
117.   it('requires an init first', async () => {
118.     await postHog.setUserProperties({'App Git Commit': 'some-git-commit'});
119. 
120.     expect(mockPostHogClient.identify).toHaveBeenCalledTimes(0);
121.   });
122. 
123.   it('calls identify', async () => {
124.     await postHog.init();
125.     await postHog.setUserProperties({'App Git Commit': 'some-git-commit'});
126. 
127.     expect(mockPostHogClient.identify).toHaveBeenCalledTimes(1);
128.     expect(mockPostHogClient.identify).toHaveBeenCalledWith(undefined, {
129.       'App Git Commit': 'some-git-commit',
130.     });
131.   });
132. 
133.   it('supports setting properties once (idempotent)', async () => {
134.     await postHog.init();
135.     await postHog.setUserProperties(
136.       {'App Git Commit': 'some-git-commit'},
137.       true,
138.     );
139. 
140.     expect(mockPostHogClient.identify).toHaveBeenCalledTimes(1);
141.     expect(mockPostHogClient.identify).toHaveBeenCalledWith(undefined, {
142.       $set_once: {
143.         'App Git Commit': 'some-git-commit',
144.       },
145.     });
146.   });
147. });
148. 
149. describe('setCoreProperties', () => {
150.   it('requires an init first', async () => {
151.     await postHog.setCoreProperties({'App Git Commit': 'some-git-commit'});
152. 
153.     expect(mockPostHogClient.identify).toHaveBeenCalledTimes(0);
154.     expect(mockPostHogClient.register).toHaveBeenCalledTimes(0);
155.   });
156. 
157.   it('calls identify', async () => {
158.     await postHog.init();
159.     await postHog.setCoreProperties({'App Git Commit': 'some-git-commit'});
160. 
